42	/**
43	 * Verify the AbfsRestOperationException error message format.
44	 * */
45	public class ITestAbfsRestOperationException extends AbstractAbfsIntegrationTest{
46	  private static final String RETRY_TEST_TOKEN_PROVIDER = "org.apache.hadoop.fs.azurebfs.oauth2.RetryTestTokenProvider";
