52	  @Test
53	  public void testAbfsRestOperationExceptionFormat() throws IOException {
54	    final AzureBlobFileSystem fs = getFileSystem();
55	    Path nonExistedFilePath1 = new Path("nonExistedPath1");
56	    Path nonExistedFilePath2 = new Path("nonExistedPath2");
57	    try {
58	      FileStatus fileStatus = fs.getFileStatus(nonExistedFilePath1);
59	    } catch (Exception ex) {
60	      String errorMessage = ex.getLocalizedMessage();
61	      String[] errorFields = errorMessage.split(",");
62	
63	      Assert.assertEquals(4, errorFields.length);
64	      // Check status message, status code, HTTP Request Type and URL.
65	      Assert.assertEquals("Operation failed: \"The specified path does not exist.\"", errorFields[0].trim());
66	      Assert.assertEquals("404", errorFields[1].trim());
67	      Assert.assertEquals("HEAD", errorFields[2].trim());
68	      Assert.assertTrue(errorFields[3].trim().startsWith("http"));
69	    }
70	
71	    try {
72	      fs.listFiles(nonExistedFilePath2, false);
73	    } catch (Exception ex) {
74	      // verify its format
75	      String errorMessage = ex.getLocalizedMessage();
76	      String[] errorFields = errorMessage.split(",");
77	
78	      Assert.assertEquals(6, errorFields.length);
79	      // Check status message, status code, HTTP Request Type and URL.
80	      Assert.assertEquals("Operation failed: \"The specified path does not exist.\"", errorFields[0].trim());
81	      Assert.assertEquals("404", errorFields[1].trim());
82	      Assert.assertEquals("GET", errorFields[2].trim());
83	      Assert.assertTrue(errorFields[3].trim().startsWith("http"));
84	      // Check storage error code and storage error message.
85	      Assert.assertEquals("PathNotFound", errorFields[4].trim());
86	      Assert.assertTrue(errorFields[5].contains("RequestId")
87	              && errorFields[5].contains("Time"));
88	    }
89	  }
