322	  private List<String> createFilesUnderDirectory(int numFiles, Path rootPath,
323	      String filenamePrefix)
324	      throws ExecutionException, InterruptedException, IOException {
325	    final List<Future<Void>> tasks = new ArrayList<>();
326	    final List<String> fileNames = new ArrayList<>();
327	    ExecutorService es = Executors.newFixedThreadPool(10);
328	    try {
329	      for (int i = 0; i < numFiles; i++) {
330	        final Path filePath = new Path(rootPath, filenamePrefix + i);
331	        Callable<Void> callable = () -> {
332	          getFileSystem().create(filePath);
333	          fileNames.add(makeQualified(filePath).toString());
334	          return null;
335	        };
336	        tasks.add(es.submit(callable));
337	      }
338	      for (Future<Void> task : tasks) {
339	        task.get();
340	      }
341	    } finally {
342	      es.shutdownNow();
343	    }
344	    return fileNames;
345	  }
